    """获取所有可用的字幕轨道"""
    if not self._player:
        return []

    tracks = []
    spu_count = self._player.video_get_spu_count()
    for i in range(spu_count):
        track_info = self._player.video_get_spu_description()[i]
        tracks.append(track_info)
    return tracks

